const PRODUCT_NOTICE_LANGS = [
  { code:'ZH', text:'积衡 Jiheng 记录现实中的钱，但不持有或处理你的钱。它是个人财务记录、整理、计算与分析软件，不是银行、电子钱包、支付工具、汇款服务或金融机构，不接收、不保管、不托管，也不实际转移用户的现实资金。积衡中显示的金额只是用户输入或系统根据记录计算出的财务记录。' },
  { code:'EN', text:'Jiheng records your real-world money. It does not hold or handle your money. It is a personal finance recording, organization, calculation and analysis software. It is NOT a bank, e-wallet, payment instrument, remittance service or financial institution, and does not receive, hold, custody, or actually transfer the user\'s real-world money. Any amount shown is a financial record entered by the user or calculated from records.' },
  { code:'BM', text:'Jiheng merekodkan wang sebenar anda. Ia tidak memegang atau mengendalikan wang anda. Ia ialah perisian merekod, menyusun, mengira dan menganalisis kewangan peribadi. Ia BUKAN bank, e-dompet, instrumen pembayaran, perkhidmatan kiriman wang atau institusi kewangan, dan tidak menerima, menyimpan, menjaga atau memindahkan wang sebenar pengguna. Jumlah yang dipaparkan ialah rekod kewangan yang dimasukkan atau dikira daripada rekod.' }
];

function renderProductNotice(){
  return `
  <div class="product-notice">
    <div class="pn-head"><div class="pn-icon">!</div><div class="pn-title">积衡 Jiheng · Product Identity · Identiti Produk</div></div>
    ${PRODUCT_NOTICE_LANGS.map(l => `<div class="pn-row"><span class="pn-flag">${l.code}</span><span class="pn-text">${l.text}</span></div>`).join('')}
  </div>`;
}

