function detectLang(){
  try{
    const saved = localStorage.getItem(LANG_KEY);
    if(saved && I18N[saved]) return saved;
    for(const k of LEGACY_LANG_KEYS){
      const old = localStorage.getItem(k);
      if(old && I18N[old]) return old;
    }
  }catch(e){}
  const nav = (navigator.language || 'zh').toLowerCase();
  if(nav.startsWith('ms')) return 'ms';
  if(nav.startsWith('en')) return 'en';
  return 'zh';
}
let LANG = detectLang();
function t(k, vars){
  const pack = I18N[LANG] || I18N.zh;
  const zhPack = I18N.zh;
  let s = pack[k];
  if(s === undefined && pack.secure && pack.secure[k] !== undefined) s = pack.secure[k];
  if(s === undefined && pack.reset  && pack.reset[k]  !== undefined) s = pack.reset[k];
  if(s === undefined && zhPack[k] !== undefined) s = zhPack[k];
  if(s === undefined && zhPack.secure && zhPack.secure[k] !== undefined) s = zhPack.secure[k];
  if(s === undefined && zhPack.reset  && zhPack.reset[k]  !== undefined) s = zhPack.reset[k];
  if(s === undefined) s = k;
  if(typeof s !== 'string') return s;
  if(vars){ Object.keys(vars).forEach(v => { s = s.replace(new RegExp('\\{'+v+'\\}','g'), vars[v]); }); }
  return s;
}
