function setLang(l){
  if(!I18N[l]) return;
  LANG = l;
  state.settings.lang = l;
  try{ localStorage.setItem(LANG_KEY, l); }catch(e){}
  saveState();
  render();
  toast(l === 'zh' ? '语言已切换为简体中文' : l === 'en' ? 'Language switched to English' : 'Bahasa ditukar ke Bahasa Melayu');
}
